-- Carga inicial: las 3 noticias que tenía el front.
INSERT INTO noticia (titulo, categoria, fecha, imagen, subtitulo, resumen, contenido, detalles) VALUES
('Campaña de Vacunación Antirrábica 2026', 'Salud Pública', '2026-10-24', 'https://images.unsplash.com/photo-1583337130417-3346a1be7dee?auto=format&fit=crop&q=80&w=800', 'Se abren nuevos puntos de atención veterinaria gratuita para perros y gatos.', 'Conoce las nuevas fechas y puntos habilitados para la inmunización antirrábica de perros y gatos en la comuna.', 'Esta semana iniciamos una nueva fecha de vacunación antirrábica e implantación de microchips en conjunto con el equipo municipal. La idea es facilitar el acceso a la atención básica para todos los vecinos que necesiten al día los controles de sus mascotas.

La rabia es una enfermedad grave pero totalmente prevenible si mantenemos las vacunas al día. La dosis debe reforzarse una vez al año, tanto en perros como en gatos, sin importar si salen poco de casa.

Atenderemos por orden de llegada. Les pedimos llevar a los perros con correa y a los gatos en su caja de transporte para evitar escapes o incidentes durante la espera.', 'Ubicación: Plaza de Armas y centros comunitarios
Horario: Lunes a viernes de 09:00 a 14:00 hrs
Requisitos: Mascotas mayores a 2 meses y carnet de vacunación anterior si lo tienen'),
('La Importancia del Microchip y Registro Legal', 'Tenencia Responsable', '2026-10-18', 'https://images.unsplash.com/photo-1548767797-d8c844163c4c?auto=format&fit=crop&q=80&w=800', 'Guía rápida sobre la implantación del dispositivo y el registro obligatorio.', 'Descubre cómo la identificación electrónica mediante microchip protege a tus animales ante casos de extravío.', 'El microchip es un pequeño dispositivo electrónico que se aplica debajo de la piel de la mascota. El procedimiento dura solo unos segundos y no requiere anestesia ni cuidados especiales posteriores.

A diferencia de lo que se cree, el chip no funciona como un GPS en tiempo real. Lo que contiene es un número único de 15 dígitos que se lee con un escáner en cualquier veterinaria o clínica municipal.

Una vez puesto el chip, es fundamental completar el registro en la plataforma nacional con los datos del tutor. Sin ese paso, el número del chip no queda asociado a nadie en caso de extravío.', 'Procedimiento: Aplicación subcutánea en consulta
Obligatoriedad: Exigido por la Ley de Tenencia Responsable
Incluye: Inscripción en la plataforma oficial'),
('Obesidad en Perros y Gatos: Nutrición Terapéutica', 'Nutrición', '2026-10-10', 'https://images.unsplash.com/photo-1537151608828-ea2b11777ee8?auto=format&fit=crop&q=80&w=800', 'Recomendaciones prácticas para prevenir la obesidad en perros y gatos.', 'Análisis clínico sobre cómo el sobrepeso afecta la calidad de vida y las alternativas de nutrición especializada.', 'El sobrepeso en animales es un problema cada vez más frecuente que suele pasar desapercibido. A largo plazo, los kilos de más generan desgaste en las articulaciones y aumentan el riesgo de diabetes o problemas cardíacos.

La causa más común suele ser la falta de medición en las porciones diarias y el exceso de premios o comida casera entre horarios. Medir la ración con un vaso dosificador o balanza marca una gran diferencia.

Si notas que tu mascota ha subido de peso o le cuesta moverse con fluidez, lo ideal es realizar una evaluación nutricional para ajustar la dieta según su edad, nivel de actividad y estado de salud.', 'Evaluación: Revisión de peso y condición corporal en consulta
Recomendación: Uso de alimentos de prescripción o bajo en calorías
Seguimiento: Controles periódicos cada 30 días');
